export interface GessoFunctionCall {
  type: "function_call";
  name: string;
  args: GessoValue[];
}

export interface GessoDimension {
  type: "dimension";
  value: number;
  unit?: string;
}

export interface GessoArray {
  type: "array";
  values: GessoValue[];
}

export interface GessoMap {
  type: "map";
  entries: Record<string, GessoValue>;
}

export interface GessoIdentifier {
  type: "identifier";
  name: string;
}

export interface GessoDocument {
  version: string;
  meta: Record<string, GessoValue>;
  definitions: Def[];
  layers: Layer[];
}

export interface Def {
  id: string;
  label?: string;
  style?: string;
  attributes: Record<string, GessoValue>;
}

export interface Layer {
  id: string;
  primitives: Primitive[];
  controls: ControlLane[];
}

export interface ControlLane {
  property: string;
  values: GessoValue[];
  times?: GessoValue[];
  curve?: string;
}

export interface Primitive {
  type: string;
  id?: string;
  attributes: Record<string, GessoValue>;
}

export function eject(doc: GessoDocument): string {
  let output = `gesso "${doc.version}" {\n`;

  // Meta
  output += `  meta @{\n`;
  for (const [key, val] of Object.entries(doc.meta)) {
    output += `    ${key}: ${serializeValue(val)},\n`;
  }
  output += `  }\n\n`;

  // Definitions
  for (const def of doc.definitions) {
    output += `  def ${def.id} "${def.label || ""}" ${def.style ? `style=${def.style} ` : ""}@{\n`;
    for (const [key, val] of Object.entries(def.attributes)) {
      output += `    ${key}: ${serializeValue(val)},\n`;
    }
    output += `  }\n\n`;
  }

  // Layers
  for (const layer of doc.layers) {
    output += `  layer "${layer.id}" {\n`;
    for (const p of layer.primitives) {
      output += `    ${p.type}${p.id ? ` "${p.id}"` : ""} @{\n`;
      for (const [key, val] of Object.entries(p.attributes)) {
        output += `      ${key}: ${serializeValue(val)},\n`;
      }
      output += `    }\n`;
    }
    output += `  }\n`;
  }

  output += `}\n`;
  return output;
}

export function indexCodebase(files: Record<string, string>): CodebaseIndex {
  const index: CodebaseIndex = {};

  for (const [filePath, content] of Object.entries(files)) {
    const lines = content.split("\n");
    const domain = getDomain(filePath);

    // Simple regex-based symbol identification
    // Matches: export function name, function name, export interface name, export class name
    const symbolRegex = /^(?:export\s+)?(?:function|interface|class|const|type)\s+([a-zA-Z0-9_]+)/;

    let currentSymbol: string | null = null;
    let startLine = 0;

    for (let i = 0; i < lines.length; i++) {
      const line = lines[i].trim();
      const match = line.match(symbolRegex);

      if (match) {
        // If we were already tracking a symbol, close it (this is a simple heuristic)
        if (currentSymbol) {
          index[currentSymbol].endLine = i;
          index[currentSymbol].content = lines.slice(index[currentSymbol].startLine - 1, i).join("\n");
        }

        currentSymbol = match[1];
        startLine = i + 1;

        index[currentSymbol] = {
          symbol: currentSymbol,
          filePath,
          startLine,
          endLine: startLine, // Placeholder
          content: "", // Placeholder
          domain,
          criticality: getCriticality(currentSymbol),
          version: "1.0.0",
        };
      }
    }

    // Close the last symbol in the file
    if (currentSymbol) {
      index[currentSymbol].endLine = lines.length;
      index[currentSymbol].content = lines.slice(index[currentSymbol].startLine - 1).join("\n");
    }
  }

  return index;
}

