export interface Token {
  type: TokenType;
  value: string;
  line: number;
  column: number;
}

export class Lexer {
  private pos = 0;
  private line = 1;
  private column = 1;

  constructor(private source: string) {}

  public tokenize(): Token[] {
    const tokens: Token[] = [];
    while (!this.isAtEnd()) {
      this.skipWhitespaceAndComments();
      if (this.isAtEnd()) break;

      const char = this.peek();

      // String Literals
      if (char === '"') {
        tokens.push(this.readString());
        continue;
      }

      // Hex Colors
      if (char === "#") {
        tokens.push(this.readHexColor());
        continue;
      }

      // Numbers and Dimensions
      if (this.isDigit(char) || (char === "-" && this.isDigit(this.peekNext()))) {
        tokens.push(this.readNumberOrDimension());
        continue;
      }

      // Identifiers, Keywords, Booleans
      if (this.isAlpha(char)) {
        tokens.push(this.readIdentifierOrKeyword());
        continue;
      }

      // Punctuation
      if ("{}@[]:,=()".includes(char)) {
        tokens.push({
          type: TokenType.Punctuation,
          value: this.advance(),
          line: this.line,
          column: this.column - 1,
        });
        continue;
      }

      throw new Error(`Unexpected character '${char}' at line ${this.line}, col ${this.column}`);
    }

    tokens.push({ type: TokenType.EOF, value: "", line: this.line, column: this.column });
    return tokens;
  }

  private readString(): Token {
    const startCol = this.column;
    this.advance(); // Skip opening "
    let value = "";
    while (!this.isAtEnd() && this.peek() !== '"') {
      if (this.peek() === "\n") {
        this.line++;
        this.column = 1;
      }
      value += this.advance();
    }
    if (this.isAtEnd()) throw new Error("Unterminated string literal");
    this.advance(); // Skip closing "
    return { type: TokenType.StringLiteral, value, line: this.line, column: startCol };
  }

  private readHexColor(): Token {
    const startCol = this.column;
    let value = this.advance(); // Skip #
    while (!this.isAtEnd() && this.isHexDigit(this.peek())) {
      value += this.advance();
    }
    return { type: TokenType.HexColor, value, line: this.line, column: startCol };
  }

  private readNumberOrDimension(): Token {
    const startCol = this.column;
    let value = "";
    if (this.peek() === "-") value += this.advance();
    while (!this.isAtEnd() && this.isDigit(this.peek())) value += this.advance();
    if (this.peek() === "." && this.isDigit(this.peekNext())) {
      value += this.advance();
      while (!this.isAtEnd() && this.isDigit(this.peek())) value += this.advance();
    }

    // Check for units
    let unit = "";
    const units = ["px", "mm", "in", "pt", "deg", "%", "s"];
    for (const u of units) {
      if (this.source.startsWith(u, this.pos)) {
        unit = u;
        for (let i = 0; i < u.length; i++) this.advance();
        break;
      }
    }

    return {
      type: TokenType.Dimension,
      value: unit ? `${value}${unit}` : value,
      line: this.line,
      column: startCol,
    };
  }

  private readIdentifierOrKeyword(): Token {
    const startCol = this.column;
    let value = "";
    while (!this.isAtEnd() && (this.isAlphaNumeric(this.peek()) || this.peek() === "_")) {
      value += this.advance();
    }

    if (value === "true" || value === "false") {
      return { type: TokenType.Boolean, value, line: this.line, column: startCol };
    }

    const keywords = ["gesso", "meta", "def", "layer", "style", "control"];
    if (keywords.includes(value)) {
      return { type: TokenType.Keyword, value, line: this.line, column: startCol };
    }

    return { type: TokenType.Identifier, value, line: this.line, column: startCol };
  }

  private skipWhitespaceAndComments(): void {
    while (!this.isAtEnd()) {
      const char = this.peek();
      if (char === " " || char === "\r" || char === "\t") {
        this.advance();
      } else if (char === "\n") {
        this.advance();
        this.line++;
        this.column = 1;
      } else if (char === "%" && this.peekNext() === "%") {
        // Line comment
        while (!this.isAtEnd() && this.peek() !== "\n") this.advance();
      } else {
        break;
      }
    }
  }

  private isAtEnd(): boolean {
    return this.pos >= this.source.length;
  }

  private peek(): string {
    return this.source[this.pos] || "";
  }

  private peekNext(): string {
    return this.source[this.pos + 1] || "";
  }

  private advance(): string {
    const char = this.source[this.pos++];
    this.column++;
    return char;
  }

  private isDigit(c: string): boolean {
    return c >= "0" && c <= "9";
  }

  private isHexDigit(c: string): boolean {
    return this.isDigit(c) || (c >= "a" && c <= "f") || (c >= "A" && c <= "F");
  }

  private isAlpha(c: string): boolean {
    return (c >= "a" && c <= "z") || (c >= "A" && c <= "Z") || c === "_";
  }

  private isAlphaNumeric(c: string): boolean {
    return this.isAlpha(c) || this.isDigit(c);
  }
}

export class Parser {
  private tokens: Token[];
  private current = 0;

  constructor(source: string) {
    const processed = this.preprocess(source);
    const lexer = new Lexer(processed);
    this.tokens = lexer.tokenize();
  }

  private preprocess(source: string): string {
    const trimmed = source.trim();
    if (trimmed.startsWith("gesso")) {
      return source;
    }

    // Auto-scaffold raw primitives into a default document structure
    return `
gesso "1.0" {
  meta @{
    title: "Gesso Sketch",
    format: "1200x800px",
    background: #ffffff
  }

  def canvas "Canvas" style=surface @{
    type: digital,
    size: [1200px, 800px],
    color: #ffffff
  }

  layer "Sketch" {
    ${source}
  }
}
    `;
  }

  public parse(): GessoDocument {
    this.consume(TokenType.Keyword, "gesso", "Expected 'gesso' keyword at start of document");
    const version = this.consume(TokenType.StringLiteral, null, "Expected version string literal").value;
    this.consume(TokenType.Punctuation, "{", "Expected '{' after gesso version");

    const doc: GessoDocument = {
      version,
      meta: {},
      definitions: [],
      layers: [],
    };

    while (!this.isAtEnd() && !this.checkPunctuation("}")) {
      const token = this.peek();

      if (token.type === TokenType.Keyword && token.value === "meta") {
        this.advance();
        doc.meta = this.parseMap();
      } else if (token.type === TokenType.Keyword && token.value === "def") {
        this.advance();
        doc.definitions.push(this.parseDef());
      } else if (token.type === TokenType.Keyword && token.value === "layer") {
        this.advance();
        doc.layers.push(this.parseLayer());
      } else if (
        token.type === TokenType.Punctuation && token.value === "@" && this.peekNext().value === "target"
      ) {
        // Still halt on target for now as it's not in Sprint 2 scope
        return doc;
      } else {
        throw new Error(`Unexpected token '${token.value}' at line ${token.line}, col ${token.column}`);
      }
    }

    this.consume(TokenType.Punctuation, "}", "Expected '}' at end of document");
    return doc;
  }

export function verifySpecAlignment(
  featureName: string,
  index: CodebaseIndex
): EvidenceReport {
  const spec = SPEC_MAP[featureName];
  if (!spec) {
    return {
      feature: featureName,
      specSection: "Unknown",
      evidence: "No spec definition found for this feature.",
      status: "Missing",
      snippets: [],
    };
  }

  const snippets: string[] = [];
  let evidence = "";

  if (featureName === "Pigment Mixing") {
    const mixFunc = index["mixColors"];
    const resolveVal = index["resolveValue"];

    if (mixFunc) {
      snippets.push(`${mixFunc.filePath} lines ${mixFunc.startLine}-${mixFunc.endLine}`);
      evidence = `${mixFunc.filePath} lines ${mixFunc.startLine}-${mixFunc.endLine} implement LERP math for RGB.`;
    }

    if (resolveVal && resolveVal.content.includes("mix")) {
      evidence += ` Nested mix() support confirmed in resolveValue.`;
    }
  } else if (featureName === "Interactivity") {
    const hitTest = index["getPrimitiveAt"];
    const mutation = index["updatePrimitivePos"];
    const mouseMove = index["handleMouseMove"];

    if (hitTest) {
      snippets.push(`${hitTest.filePath} lines ${hitTest.startLine}-${hitTest.endLine}`);
      evidence += `Hit-testing logic found in ${hitTest.filePath}. `;
    }
    if (mutation) {
      snippets.push(`${mutation.filePath} lines ${mutation.startLine}-${mutation.endLine}`);
      evidence += `AST mutation logic found in ${mutation.filePath}. `;
    }
    if (mouseMove) {
      snippets.push(`${mouseMove.filePath} lines ${mouseMove.startLine}-${mouseMove.endLine}`);
      evidence += `Live loop sync found in ${mouseMove.filePath}. `;
    }
  }

  return {
    feature: featureName,
    specSection: spec.section,
    evidence: evidence || "No direct evidence found in codebase index.",
    status: evidence ? "Spec Compliant" : "Missing",
    snippets,
  };
}

export interface EvidenceReport {
  feature: string;
  specSection: string;
  evidence: string;
  status: "Spec Compliant" | "Partial" | "Missing";
  snippets: string[];
}

export function resolveDocument(doc: GessoDocument): GessoDocument {
  const resolvedLayers = doc.layers.map((layer) => {
    const lastState: Record<string, GessoValue> = {};
    let cursorX = 0;
    let cursorY = 0;
    const padding = 20;

    const resolvedPrimitives = layer.primitives.map((p) => {
      const attrs = { ...p.attributes };

      // Sticky State Resolution
      const stickyKeys = ["fill", "stroke", "stroke_width", "brush"];
      stickyKeys.forEach((key) => {
        if (attrs[key] === undefined && lastState[key] !== undefined) {
          attrs[key] = lastState[key];
        } else if (attrs[key] !== undefined) {
          lastState[key] = attrs[key];
        }
      });

      // Relative Positioning (Flow Layout)
      if (attrs.pos === undefined) {
        attrs.pos = { type: "array", values: [cursorX, cursorY] };
      } else {
        const pos = resolveValue(attrs.pos, doc.definitions) as number[];
        if (Array.isArray(pos)) {
          cursorX = pos[0];
          cursorY = pos[1];
        }
      }

      // Calculate width for next element
      let width = 0;
      if (p.type === "rect") {
        const size = resolveValue(
          attrs.size || { type: "array", values: [100, 100] },
          doc.definitions
        ) as number[];
        width = Array.isArray(size) ? size[0] : 100;
      } else if (p.type === "circle") {
        const radius = resolveValue(
          attrs.radius || { type: "dimension", value: 50 },
          doc.definitions
        ) as number;
        width = (typeof radius === "number" ? radius : 50) * 2;
      } else if (p.type === "path") {
        const points = resolveValue(
          attrs.points || { type: "array", values: [] },
          doc.definitions
        ) as any[];
        if (Array.isArray(points)) {
          let minX = Infinity, maxX = -Infinity;
          points.forEach((seg) => {
            if (Array.isArray(seg)) {
              if (seg.length === 8) {
                minX = Math.min(minX, seg[0], seg[6]);
                maxX = Math.max(maxX, seg[0], seg[6]);
              } else if (seg.length === 2) {
                minX = Math.min(minX, seg[0]);
                maxX = Math.max(maxX, seg[0]);
              }
            }
          });
          width = (maxX - minX) > 0 ? (maxX - minX) : 100;
        } else {
          width = 100;
        }
      }

      // Update cursor for next
      const currentPos = resolveValue(attrs.pos, doc.definitions) as number[];
      if (Array.isArray(currentPos)) {
        cursorX = currentPos[0] + width + padding;
      }

      return { ...p, attributes: attrs };
    });

    return { ...layer, primitives: resolvedPrimitives };
  });

  return { ...doc, layers: resolvedLayers };
}

export function updatePrimitivePos(
  doc: GessoDocument,
  layerId: string,
  primitiveIndex: number,
  newX: number,
  newY: number
): GessoDocument {
  const newLayers = doc.layers.map((layer) => {
    if (layer.id !== layerId) return layer;

    const newPrimitives = layer.primitives.map((p, i) => {
      if (i !== primitiveIndex) return p;
      return {
        ...p,
        attributes: {
          ...p.attributes,
          pos: { type: "array", values: [newX, newY] } as any,
        },
      };
    });

    return { ...layer, primitives: newPrimitives };
  });

  return { ...doc, layers: newLayers };
}

export function resolveValue(
  value: GessoValue,
  definitions: Def[]
): ResolvedValue {
  if (typeof value === "string" || typeof value === "number" || typeof value === "boolean") {
    return value;
  }

  switch (value.type) {
    case "function_call": {
      if (value.name === "mix") {
        const color1 = resolveValue(value.args[0], definitions);
        const color2 = resolveValue(value.args[1], definitions);
        const ratio = resolveValue(value.args[2], definitions) as number;
        return mixColors(color1, color2, ratio);
      }
      return value;
    }
    case "identifier": {
      // Look up in definitions
      const found = definitions.find((d) => d.id === value.name);
      if (found) {
        // If it's a paint or color-like def, we usually want its 'color' attribute
        if (found.attributes.color) {
          return resolveValue(found.attributes.color, definitions);
        }
        // Fallback to the whole attribute map if no specific 'color'
        return resolveMap(found.attributes, definitions);
      }
      // If not found, return the name as a string (might be a named color or built-in)
      return value.name;
    }
    case "dimension":
      // For Sprint 2, we just return the numeric value
      // In later sprints, we might handle unit conversion
      return value.value;
    case "array":
      return value.values.map((v) => resolveValue(v, definitions));
    case "map":
      return resolveMap(value.entries, definitions);
    default:
      return value;
  }
}
